def intersection(nums1, nums2):
    # Convert first list to a set for fast lookup
    lookup = set(nums1)
    result = set()
    # Iterate over the second array
    for num in nums2:
        # If num is in lookup, it's part of intersection
        if num in lookup:
            result.add(num)
    # Convert set to list for the required output
    return list(result)
